let store,storage,audio,media,engine,output,selected=null,inspectorTab='properties',drag=null,saveTimer,autosaveError=false,meterTimer,statsTimer,dialogSubmit=null,menuAnchor=null;
const cleanType={camera:'Video capture device',screen:'Display capture',microphone:'Microphone input',image:'Image',video:'Media source',audio:'Audio file',text:'Text',color:'Color',generator:'Motion background',lowerthird:'Lower third',badge:'Broadcast badge',countdown:'Countdown',tone:'Test tone'};
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'info':'check')+`<span>${esc(message)}</span><button class="icon-btn" aria-label="Dismiss">${icon('close')}</button>`;el.querySelector('button').onclick=()=>el.remove();$('#toasts').append(el);setTimeout(()=>el.remove(),error?14000:6500);}
const safe=fn=>async(...args)=>{try{return await fn(...args);}catch(e){if(e.name!=='AbortError')toast(e.message||String(e),true);}};
const selectedItem=()=>store.scene()?.items.find(i=>i.id===selected);
const selectedSource=()=>store.project.sources[selectedItem()?.sourceId];
function selectItem(id){selected=id;renderSources();renderInspector();renderSelectionLabel();drawOverlay();}
function requireItem(){const item=selectedItem();if(!item)throw new Error('Select a source in the preview or Sources panel first.');return item;}
function commit(label,fn){store.mutate(label,fn);}
function setPreview(id){if(!store.project.scenes.some(s=>s.id===id))return;store.project.preview=id;selected=null;if(!store.project.settings.studio)engine.take('cut');store.emit('Select preview');}
function recordStore(){clearTimeout(saveTimer);$('#save-status').innerHTML='<span class="dot purple"></span> Saving…';saveTimer=setTimeout(()=>{try{localStorage.setItem('signalforge-project-v1',JSON.stringify(store.project));$('#save-status').innerHTML='<span class="dot green"></span> All changes saved';}catch{if(!autosaveError){autosaveError=true;toast('Browser storage is full or unavailable. Export your project to keep a copy.',true);}$('#save-status').textContent='Export to save';}},400);}
function renderScenes(){const p=store.project;$('#scene-count').textContent=p.scenes.length;$('#scene-list').innerHTML=p.scenes.map((s,i)=>`<div class="scene-row ${s.id===p.preview?'selected':''}" data-scene="${s.id}" draggable="true" tabindex="0" role="button" aria-label="Preview ${esc(s.name)}"><span class="scene-number">${String(i+1).padStart(2,'0')}</span><span class="row-name">${esc(s.name)}</span>${s.id===p.preview?'<span class="row-tag">PREVIEW</span>':''}${s.id===engine.programState.scene.id?'<span class="live-dot" title="Program"></span>':''}</div>`).join('');}
function renderSources(){const scene=store.scene();if(!scene)return;$('#source-count').textContent=scene.items.length;$('#source-list').innerHTML=scene.items.length?[...scene.items].reverse().map(i=>{const s=store.project.sources[i.sourceId];return `<div class="source-row ${i.id===selected?'selected':''} ${!i.visible?'is-hidden':''}" data-item="${i.id}" draggable="true" role="button" tabindex="0" aria-label="Select ${esc(s.name)}"><span class="source-icon">${icon(s.type)}</span><span class="row-name" title="${esc(s.name)}">${esc(s.name)}</span><button class="icon-btn" data-action="toggle-visible" data-id="${i.id}" title="${i.visible?'Hide':'Show'} source">${icon(i.visible?'eye':'eyeoff')}</button><button class="icon-btn" data-action="toggle-lock" data-id="${i.id}" title="${i.locked?'Unlock':'Lock'} source">${icon(i.locked?'lock':'unlock')}</button></div>`;}).join(''):`<div class="empty-panel">${icon('layers')}<div>Your scene is a blank canvas.</div><button class="text-button" data-action="add-source">Add your first source</button></div>`;}
