boot().catch(error=>{console.error(error);$('#loading').innerHTML=`<h2>Studio could not initialize</h2><p>${esc(error.message)}</p><p>Serve the app from localhost or HTTPS. IndexedDB and JavaScript modules must be enabled.</p><button class="btn" id="retry-canvas">Retry with Canvas compositor</button>`;$('#retry-canvas').onclick=()=>location.search='?canvas';});
